class Solution {
    fun constructArray(n:Int,k:Int):IntArray{
        val answer=IntArray(n);
        var index=0;
        var left=1;
        var right=k+1;
        while(left<=right){
            answer[index++]=left++;
            if(left<=right)answer[index++]=right--
        };
        for(value in k+2..n)answer[index++]=value;
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<int> constructArray(int n,int k){
        vector<int> answer;
        int left=1,right=k+1;
        while(left<=right){
            answer.push_back(left++);
            if(left<=right)answer.push_back(right--);
        }
        for(int value=k+2;value<=n;++value)answer.push_back(value);
        return answer;
    }
};
